style.css:
@-moz-document regexp("(?!https://v2.horsereality.com).*") {
/* Main page */
html,
body {
    background: #ded6d0 !important;
    color: #594e49 !important;
}

/* General text */
body,
p,
span,
div,
label,
li,
td,
th {
    color: #594e49;
}

/* Links */
a {
    color: #594e49 !important;
    transition: color 0.2s ease, opacity 0.2s ease;
}

a:hover {
    color: #887364 !important;
}

/* Headings */
h1,
h2,
h3,
h4,
h5,
h6 {
    color: #594e49 !important;
}

/* Cards / panels / containers */
.card,
.panel,
.container,
section,
article {
    background-color: #ded6d0 !important;
    border-color: #89807B !important;
}

/* Inputs */
input,
textarea,
select {
    background: #ded6d0 !important;
    color: #594e49 !important;
    border: 1px solid #89807B !important;
    border-radius: 6px;
}

input::placeholder,
textarea::placeholder {
    color: #89807B !important;
}

input:focus,
textarea:focus,
select:focus {
    outline: none !important;
    border-color: #887364 !important;
    box-shadow: 0 0 0 2px rgba(136, 115, 100, 0.2) !important;
}

/* Buttons */
button,
.button,
input[type="button"],
input[type="submit"] {
    background: #594e49 !important;
    color: #ded6d0 !important;
    border: 1px solid #594e49 !important;
    border-radius: 6px;
    transition: background 0.2s ease, transform 0.15s ease;
}

button:hover,
.button:hover,
input[type="button"]:hover,
input[type="submit"]:hover {
    background: #887364 !important;
    border-color: #887364 !important;
}

button:active,
.button:active {
    transform: translateY(1px);
}

/* Secondary buttons */
button.secondary,
.button.secondary {
    background: #89807B !important;
    color: #ded6d0 !important;
}

/* Navigation / headers */
header,
nav,
.navbar,
.topbar {
    background: #594e49 !important;
    color: #ded6d0 !important;
}

header a,
nav a,
.navbar a,
.topbar a {
    color: #ded6d0 !important;
}

header a:hover,
nav a:hover,
.navbar a:hover,
.topbar a:hover {
    color: #ded6d0 !important;
    opacity: 0.75;
}

/* Borders and dividers */
hr,
.divider,
.border {
    border-color: #89807B !important;
}

/* Tables */
table {
    background: #ded6d0 !important;
    color: #594e49 !important;
    border-color: #89807B !important;
}

th {
    background: #887364 !important;
    color: #ded6d0 !important;
}

td {
    border-color: #89807B !important;
}

tr:hover td {
    background: rgba(136, 115, 100, 0.12) !important;
}

/* Code blocks */
code,
pre {
    background: #594e49 !important;
    color: #ded6d0 !important;
    border-radius: 6px;
}

pre {
    padding: 1em;
}

/* Selection */
::selection {
    background: #887364 !important;
    color: #ded6d0 !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 10px;
    height: 10px;
}

::-webkit-scrollbar-track {
    background: #ded6d0;
}

::-webkit-scrollbar-thumb {
    background: #89807B;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: #887364;
}

/* Subtle shadows */
.card,
.panel,
section,
article,
.container {
    box-shadow: 0 2px 10px rgba(89, 78, 73, 0.08);
}

/* Images */
img {
    border-radius: 4px;
}

/* Disabled elements */
button:disabled,
input:disabled,
select:disabled {
    background: #89807B !important;
    color: #ded6d0 !important;
    opacity: 0.6;
}
}
